'use client'

/**
 * AppointmentWizard — shared 4-step wizard used by both:
 *   - /appointments/new (full-page)
 *   - AppointmentCreateDrawer (Sheet)
 *
 * Step order: Client → Service → Artist → Time
 * The Artist step is auto-skipped when the studio has ≤1 active artist.
 */

import {
  useState,
  useEffect,
  useCallback,
  useRef,
  useMemo,
} from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Skeleton } from '@/components/ui/skeleton'
import { BookingStepIndicator } from '@/components/booking/BookingStepIndicator'
import { ServicePicker } from '@/components/booking/ServicePicker'
import { ArtistPicker } from '@/components/booking/ArtistPicker'
import { SlotPicker } from '@/components/booking/SlotPicker'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { formatCurrency } from '@/lib/utils'
import {
  ChevronLeft,
  ChevronRight,
  Loader2,
  Clock3,
  CalendarX,
} from 'lucide-react'
import { cn } from '@/lib/utils'

// ─── Types ────────────────────────────────────────────────────────────────────

interface Service {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
  specialties: string[]
}

interface NewClientData {
  first_name: string
  last_name: string
  email: string
  phone: string
}

interface DraftState {
  clientId: string | null
  serviceId: string | null
  artistId: string | null
  slot: string | null
  notes: string
}

// ─── Step config ──────────────────────────────────────────────────────────────

const ALL_STEPS = [
  { label: 'Client' },
  { label: 'Service' },
  { label: 'Artist' },
  { label: 'Time' },
] as const

type StepIndex = 0 | 1 | 2 | 3

const DRAFT_KEY_PREFIX = 'inkos_appt_draft_v2'

function getDraftKey(studioId: string | null, userId: string | null): string {
  return `${DRAFT_KEY_PREFIX}_${studioId ?? 'unknown'}_${userId ?? 'anonymous'}`
}

// ─── Props ────────────────────────────────────────────────────────────────────

export interface AppointmentWizardProps {
  /** Studio ID from server auth — may be null on first load */
  studioId: string | null
  /** Authenticated user ID — used for draft scoping */
  userId: string | null
  /**
   * Called on successful booking submission.
   * Full-page variant: navigates to booking detail.
   * Drawer variant: closes the sheet and refetches.
   */
  onSuccess: (bookingId: string) => void
  /**
   * Called when the user wants to cancel/close.
   * Full-page: navigate back. Drawer: close sheet.
   */
  onCancel: () => void
  /**
   * Pre-select a slot — used by calendar drag-to-create from the drawer.
   */
  defaultSlot?: string | null
  /**
   * Controls footer layout.
   * 'page'   — sticky bottom bar on mobile, inline on desktop, "Cancel" on step 0.
   * 'drawer' — always inline in the Sheet footer.
   */
  mode?: 'page' | 'drawer'
}

// ─── Sub-components ───────────────────────────────────────────────────────────

function SummarySidebar({
  service,
  slot,
  clientName,
  artistName,
  notes,
  onNotesChange,
  draftSaved,
}: {
  service: Service | null
  slot: string | null
  clientName: string | null
  artistName: string | null
  notes: string
  onNotesChange: (v: string) => void
  draftSaved: boolean
}) {
  return (
    <div className="rounded-xl border border-border/60 p-5 space-y-4 sticky top-8">
      <p className="text-sm font-semibold">Summary</p>

      <div className="space-y-3 text-sm">
        <div>
          <p className="text-xs text-muted-foreground">Client</p>
          {clientName ? (
            <div className="flex items-center gap-1.5 mt-0.5">
              <div className="h-6 w-6 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                <span className="text-xs font-semibold text-primary">
                  {clientName[0]}
                </span>
              </div>
              <p className="font-medium">{clientName}</p>
            </div>
          ) : (
            <p className="text-muted-foreground mt-0.5">Not selected</p>
          )}
        </div>

        <div>
          <p className="text-xs text-muted-foreground">Service</p>
          {service ? (
            <div className="flex items-center gap-1.5 mt-0.5">
              {service.color && (
                <span
                  className="h-2.5 w-2.5 rounded-full shrink-0"
                  style={{ backgroundColor: service.color }}
                />
              )}
              <p className="font-medium">
                {service.name}
                <span className="text-muted-foreground font-normal ml-1">
                  · {service.duration_min} min
                </span>
              </p>
            </div>
          ) : (
            <p className="text-muted-foreground mt-0.5">Not selected</p>
          )}
        </div>

        {artistName && (
          <div>
            <p className="text-xs text-muted-foreground">Artist</p>
            <p className="font-medium mt-0.5">{artistName}</p>
          </div>
        )}

        <div>
          <p className="text-xs text-muted-foreground">Time</p>
          {slot ? (
            <p className="font-medium mt-0.5">
              {new Date(slot).toLocaleDateString('en-US', {
                weekday: 'short',
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
              })}
            </p>
          ) : (
            <p className="text-muted-foreground mt-0.5">Not selected</p>
          )}
        </div>

        {service && (
          <>
            <div>
              <p className="text-xs text-muted-foreground">Price</p>
              <p className="font-medium tabular-nums mt-0.5">
                {formatCurrency(service.base_price_cents)}
              </p>
            </div>
            {service.deposit_required && service.deposit_cents > 0 && (
              <div>
                <p className="text-xs text-muted-foreground">Deposit</p>
                <p className="font-medium tabular-nums mt-0.5 text-warning-foreground">
                  {formatCurrency(service.deposit_cents)} required
                </p>
              </div>
            )}
          </>
        )}
      </div>

      <div className="border-t border-border/40" />

      <div className="space-y-1.5">
        <Label htmlFor="wizard-notes" className="text-xs">
          Internal notes
        </Label>
        <Textarea
          id="wizard-notes"
          value={notes}
          onChange={(e) => onNotesChange(e.target.value)}
          placeholder="Visible only to staff..."
          className="text-sm min-h-[72px] resize-none"
          maxLength={2000}
        />
        {draftSaved && (
          <p className="flex items-center gap-1 text-xs text-muted-foreground">
            <Clock3 className="h-3 w-3" />
            Draft saved
          </p>
        )}
      </div>
    </div>
  )
}

// ─── Main component ───────────────────────────────────────────────────────────

export function AppointmentWizard({
  studioId,
  userId,
  onSuccess,
  onCancel,
  defaultSlot = null,
  mode = 'page',
}: AppointmentWizardProps) {
  const queryClient = useQueryClient()

  // ── Step state ──────────────────────────────────────────────────────────────
  const [step, setStep] = useState<StepIndex>(0)
  const [direction, setDirection] = useState<'forward' | 'back'>('forward')

  // ── Form state ──────────────────────────────────────────────────────────────
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [clientName, setClientName] = useState<string | null>(null)
  const [newClientData, setNewClientData] = useState<NewClientData | null>(null)
  const [selectedServiceId, setSelectedServiceId] = useState<string | null>(null)
  const [selectedArtistId, setSelectedArtistId] = useState<string | null>(null)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(defaultSlot)
  const [notes, setNotes] = useState('')

  // ── Draft persistence ───────────────────────────────────────────────────────
  const [draftSaved, setDraftSaved] = useState(false)
  const [draftRestoredBanner, setDraftRestoredBanner] = useState(false)
  const draftKey = getDraftKey(studioId, userId)

  useEffect(() => {
    try {
      const raw = localStorage.getItem(draftKey)
      if (!raw) return
      const draft = JSON.parse(raw) as DraftState
      if (draft.clientId) setSelectedClientId(draft.clientId)
      if (draft.serviceId) setSelectedServiceId(draft.serviceId)
      if (draft.artistId) setSelectedArtistId(draft.artistId)
      if (draft.slot) setSelectedSlot(draft.slot)
      if (draft.notes) setNotes(draft.notes)
      setDraftRestoredBanner(true)
    } catch {
      // ignore malformed draft
    }
  }, [draftKey])

  const saveTimeout = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => {
    if (saveTimeout.current) clearTimeout(saveTimeout.current)
    saveTimeout.current = setTimeout(() => {
      const draft: DraftState = {
        clientId: selectedClientId,
        serviceId: selectedServiceId,
        artistId: selectedArtistId,
        slot: selectedSlot,
        notes,
      }
      try {
        localStorage.setItem(draftKey, JSON.stringify(draft))
        setDraftSaved(true)
      } catch {
        // QuotaExceededError — silently drop
      }
    }, 1000)
    return () => {
      if (saveTimeout.current) clearTimeout(saveTimeout.current)
    }
  }, [draftKey, selectedClientId, selectedServiceId, selectedArtistId, selectedSlot, notes])

  const clearDraft = useCallback(() => {
    localStorage.removeItem(draftKey)
    setDraftSaved(false)
    setDraftRestoredBanner(false)
  }, [draftKey])

  // ── Data fetching ───────────────────────────────────────────────────────────

  const { data: servicesData, isLoading: servicesLoading } = useQuery<{ data: Service[] }>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      return res.json() as Promise<{ data: Service[] }>
    },
    enabled: step >= 1,
  })

  // Fetch all active artists (to determine skip logic) — enabled from step 1
  // so we know the count by the time Artist step would be shown.
  const { data: artistsData, isLoading: artistsLoading } = useQuery<{ data: Artist[] }>({
    queryKey: ['artists', 'by-service', selectedServiceId],
    queryFn: async () => {
      const url = selectedServiceId
        ? `/api/artists?service_id=${selectedServiceId}&status=active`
        : '/api/artists?status=active'
      const res = await fetch(url)
      if (!res.ok) throw new Error('Failed to fetch artists')
      return res.json() as Promise<{ data: Artist[] }>
    },
    enabled: step >= 1,
  })

  const services = servicesData?.data ?? []
  const artists = artistsData?.data ?? []
  const selectedService = services.find((s) => s.id === selectedServiceId) ?? null
  const selectedArtist = artists.find((a) => a.id === selectedArtistId) ?? null

  // ── Artist auto-skip logic ──────────────────────────────────────────────────
  // Skip artist step when there is exactly one active artist for the selected
  // service (or for the whole studio when no service filter applies).
  const shouldSkipArtistStep = useMemo(() => {
    if (artistsLoading) return false
    return artists.length <= 1
  }, [artists.length, artistsLoading])

  // Canonical visible steps (Artist removed when skipping)
  const visibleSteps = useMemo(
    () =>
      shouldSkipArtistStep
        ? [{ label: 'Client' }, { label: 'Service' }, { label: 'Time' }]
        : [...ALL_STEPS],
    [shouldSkipArtistStep],
  )

  // Map logical step index → visible step index (for the indicator).
  // Logical: 0=Client, 1=Service, 2=Artist, 3=Time
  // When skipping artist: Time collapses to visible index 2
  function toVisibleStep(logical: StepIndex): number {
    if (shouldSkipArtistStep && logical === 3) return 2
    if (shouldSkipArtistStep && logical === 2) {
      // This logical step shouldn't be reached when skipping
      return 2
    }
    return logical
  }

  // Auto-assign single artist when entering artist step or when skipping
  useEffect(() => {
    if (shouldSkipArtistStep && artists.length === 1 && artists[0]) {
      setSelectedArtistId(artists[0].id)
    }
  }, [shouldSkipArtistStep, artists])

  // ── Navigation ──────────────────────────────────────────────────────────────

  const canProceedFromStep = useCallback(
    (s: StepIndex): boolean => {
      if (s === 0) return !!(selectedClientId ?? newClientData)
      if (s === 1) return !!selectedServiceId
      if (s === 2) {
        // Artist step — only reached when not skipping
        return !!selectedArtistId
      }
      if (s === 3) return !!selectedSlot
      return false
    },
    [selectedClientId, newClientData, selectedServiceId, selectedArtistId, selectedSlot],
  )

  const canProceed = canProceedFromStep(step)

  const nextLogicalStep = useCallback(
    (current: StepIndex): StepIndex => {
      const next = (current + 1) as StepIndex
      // Skip step 2 (Artist) when shouldSkipArtistStep
      if (next === 2 && shouldSkipArtistStep) return 3
      return next
    },
    [shouldSkipArtistStep],
  )

  const prevLogicalStep = useCallback(
    (current: StepIndex): StepIndex => {
      const prev = (current - 1) as StepIndex
      // Skip step 2 (Artist) going backwards when shouldSkipArtistStep
      if (prev === 2 && shouldSkipArtistStep) return 1
      return prev
    },
    [shouldSkipArtistStep],
  )

  const isLastStep = step === 3 || (shouldSkipArtistStep && step === 1 && false)
  // The actual final logical step is 3 (Time). When skipping artist we still
  // end at step 3.
  const isFinalStep = step === 3

  const goNext = useCallback(() => {
    if (!canProceed) return
    setDirection('forward')
    setStep((s) => nextLogicalStep(s as StepIndex))
  }, [canProceed, nextLogicalStep])

  const goBack = useCallback(() => {
    if (step === 0) {
      onCancel()
      return
    }
    setDirection('back')
    setStep((s) => prevLogicalStep(s as StepIndex))
  }, [step, onCancel, prevLogicalStep])

  // ── Submit ──────────────────────────────────────────────────────────────────

  const createMutation = useMutation({
    mutationFn: async () => {
      // Create client inline if needed
      let clientId = selectedClientId
      if (!clientId && newClientData) {
        const res = await fetch('/api/clients', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newClientData),
        })
        if (!res.ok) {
          const err = await res.json() as { error?: string }
          throw new Error(err.error ?? 'Failed to create client')
        }
        const { data } = await res.json() as { data: { id: string } }
        clientId = data.id
      }

      if (!clientId || !selectedArtistId || !selectedSlot || !selectedServiceId || !selectedService) {
        throw new Error('All fields are required')
      }

      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          artist_id: selectedArtistId,
          service_id: selectedServiceId,
          scheduled_at: selectedSlot,
          duration_min: selectedService.duration_min,
          price_cents: selectedService.base_price_cents,
          deposit_cents: selectedService.deposit_cents,
          ...(notes ? { notes } : {}),
          source: 'internal',
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        if (err.error?.includes('time slot') || err.error?.includes('23P01')) {
          throw new Error('That time slot is already booked for this artist')
        }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      const { data } = await res.json() as { data: { id: string } }
      return data.id
    },
    onSuccess: (bookingId) => {
      clearDraft()
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      toast.success('Appointment created')
      onSuccess(bookingId)
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'appointment wizard create failed')
      // Conflict error → jump back to Time step so user can repick
      if (err.message.includes('time slot')) {
        setStep(3)
        setSelectedSlot(null)
      }
    },
  })

  // ── Animation class ─────────────────────────────────────────────────────────

  const stepAnimClass =
    direction === 'forward'
      ? 'animate-in fade-in-0 slide-in-from-right-4 duration-200'
      : 'animate-in fade-in-0 slide-in-from-left-4 duration-200'

  // ── Render ──────────────────────────────────────────────────────────────────

  const stepContent = (
    <div
      key={`step-${step}`}
      className={cn(stepAnimClass, 'space-y-4')}
      data-testid={`wizard-step-${step}`}
    >
      {/* Step 0: Client */}
      {step === 0 && (
        <>
          <p className="text-sm font-medium">Who is this appointment for?</p>
          <ClientFinder
            selectedClientId={selectedClientId}
            onSelectClient={(id, name) => {
              setSelectedClientId(id)
              setClientName(name ?? null)
              setNewClientData(null)
            }}
            onNewClient={(data) => {
              setNewClientData(data)
              setSelectedClientId(null)
              setClientName(`${data.first_name} ${data.last_name}`.trim())
            }}
          />
        </>
      )}

      {/* Step 1: Service */}
      {step === 1 && (
        <>
          <p className="text-sm font-medium">Which service?</p>
          {services.length === 0 && !servicesLoading ? (
            <div className="rounded-xl border border-border/60 p-8 text-center space-y-3">
              <CalendarX className="h-10 w-10 text-muted-foreground/40 mx-auto" />
              <p className="text-sm font-medium">No services configured</p>
              <a
                href="/settings/services"
                className="text-xs text-primary hover:underline"
              >
                Configure services →
              </a>
            </div>
          ) : (
            <ServicePicker
              services={services}
              selectedId={selectedServiceId}
              onSelect={setSelectedServiceId}
              isLoading={servicesLoading}
            />
          )}
        </>
      )}

      {/* Step 2: Artist (only when not skipped) */}
      {step === 2 && !shouldSkipArtistStep && (
        <>
          <p className="text-sm font-medium">Choose an artist</p>
          {selectedService && (
            <p className="text-xs text-muted-foreground">
              For: {selectedService.name} ({selectedService.duration_min} min)
            </p>
          )}
          <ArtistPicker
            artists={artists}
            selectedId={selectedArtistId}
            onSelect={setSelectedArtistId}
            isLoading={artistsLoading}
          />
        </>
      )}

      {/* Step 3: Time */}
      {step === 3 && (
        <>
          <div>
            <p className="text-sm font-medium">Pick a date and time</p>
            {selectedArtist && (
              <p className="text-xs text-muted-foreground mt-1">
                With {selectedArtist.display_name}
              </p>
            )}
          </div>
          <SlotPicker
            artistId={selectedArtistId ?? (artists[0]?.id ?? null)}
            serviceId={selectedServiceId}
            selectedSlot={selectedSlot}
            onSelectSlot={(slot) => {
              setSelectedSlot(slot || null)
              // Auto-assign single artist if not set yet
              if (!selectedArtistId && artists[0]) {
                setSelectedArtistId(artists[0].id)
              }
            }}
          />
        </>
      )}
    </div>
  )

  const footer = (
    <div
      className={cn(
        'flex items-center justify-between gap-3',
        mode === 'page' && [
          'pt-6 border-t border-border/40 mt-8',
          'fixed bottom-0 left-0 right-0 bg-background border-t border-border/40 px-4 py-3',
          'lg:static lg:border-t lg:bg-transparent lg:px-0 lg:py-0',
        ],
        mode === 'drawer' && 'border-t border-border/40 px-6 py-4',
      )}
      style={
        mode === 'page'
          ? { paddingBottom: 'max(0.75rem, env(safe-area-inset-bottom))' }
          : undefined
      }
    >
      <Button variant={mode === 'drawer' ? 'outline' : 'ghost'} onClick={goBack}>
        <ChevronLeft className="h-4 w-4 mr-1" />
        {step === 0 ? 'Cancel' : 'Back'}
      </Button>

      {!isFinalStep ? (
        <Button
          disabled={!canProceed}
          onClick={goNext}
          data-testid="wizard-next"
        >
          Next
          <ChevronRight className="h-4 w-4 ml-1" />
        </Button>
      ) : (
        <Button
          disabled={!canProceed || createMutation.isPending}
          onClick={() => createMutation.mutate()}
          data-testid="wizard-submit"
        >
          {createMutation.isPending ? (
            <>
              <Loader2
                aria-hidden="true"
                className="h-4 w-4 animate-spin mr-1.5"
              />
              Booking…
            </>
          ) : (
            'Book appointment'
          )}
        </Button>
      )}
    </div>
  )

  if (mode === 'drawer') {
    return (
      <>
        {/* Step indicator in drawer header area */}
        <div className="px-6 pt-2 pb-4" data-testid="appointment-wizard">
          <BookingStepIndicator
            steps={visibleSteps}
            currentStep={toVisibleStep(step)}
            className="mt-1"
          />
        </div>

        {/* Scrollable step content */}
        <div className="flex-1 overflow-y-auto px-6 pb-4 space-y-4">
          {/* Draft restored banner */}
          {draftRestoredBanner && (
            <div className="flex items-center justify-between rounded-lg bg-muted/40 border border-border/60 px-3 py-2 text-xs">
              <span>Draft restored from last session.</span>
              <button
                type="button"
                className="text-muted-foreground hover:text-foreground ml-2"
                onClick={() => {
                  clearDraft()
                  setSelectedClientId(null)
                  setClientName(null)
                  setNewClientData(null)
                  setSelectedServiceId(null)
                  setSelectedArtistId(null)
                  setSelectedSlot(defaultSlot)
                  setNotes('')
                  setDraftRestoredBanner(false)
                }}
              >
                Clear ×
              </button>
            </div>
          )}
          {stepContent}

          {/* Inline notes in drawer (no sidebar available) */}
          {step === 3 && (
            <div className="space-y-1.5 pt-2">
              <Label htmlFor="drawer-wizard-notes" className="text-xs">
                Internal notes
              </Label>
              <Textarea
                id="drawer-wizard-notes"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Visible only to staff..."
                className="text-sm min-h-[72px] resize-none"
                maxLength={2000}
              />
              {draftSaved && (
                <p className="flex items-center gap-1 text-xs text-muted-foreground">
                  <Clock3 className="h-3 w-3" />
                  Draft saved
                </p>
              )}
            </div>
          )}

          {/* Compact summary block in drawer on final step */}
          {step === 3 && selectedService && selectedSlot && (
            <div className="rounded-lg bg-muted/40 border border-border/60 p-3 space-y-1.5 text-sm">
              <p className="font-medium text-xs text-muted-foreground uppercase tracking-wide">
                Summary
              </p>
              {clientName && <p className="font-medium">{clientName}</p>}
              <p>{selectedService.name}</p>
              {selectedArtist && (
                <p className="text-xs text-muted-foreground">
                  With {selectedArtist.display_name}
                </p>
              )}
              <p className="tabular-nums text-xs text-muted-foreground">
                {new Date(selectedSlot).toLocaleDateString('en-US', {
                  weekday: 'short',
                  month: 'short',
                  day: 'numeric',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </p>
