import { useEffect, startTransition } from 'react'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { AppointmentWizard } from '@/components/appointments/AppointmentWizard'
import { toast } from 'sonner'

interface AppointmentCreateDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Pass null for create mode; pass an ID for edit mode (edit is handled elsewhere). */
  editingId: string | null
  defaultStart?: Date
  defaultEnd?: Date
  onSuccess: () => void
  /** Studio ID forwarded from the authenticated layout. */
  studioId?: string | null
  /** Authenticated user ID for draft scoping. */
  userId?: string | null
}

export function AppointmentCreateDrawer({
  open,
  onOpenChange,
  editingId,
  defaultStart,
  onSuccess,
  studioId = null,
  userId = null,
}: AppointmentCreateDrawerProps) {
  const isCreating = !editingId

  // Reset when closed externally
  useEffect(() => {
    if (!open) return
    // Nothing to reset — AppointmentWizard owns its own state and resets
    // via its own draft/restore flow.
    startTransition(() => {
      // Intentionally empty: wizard resets on key change when needed
    })
  }, [open])

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-lg flex flex-col overflow-hidden p-0"
      >
        <SheetHeader className="px-6 pt-6 pb-0 border-b border-border/40">
          <SheetTitle>
            {editingId ? 'Edit Appointment' : 'New Appointment'}
          </SheetTitle>
          <SheetDescription className="sr-only">
            {editingId
              ? 'Modify appointment details'
              : 'Book a new appointment in four steps: client, service, artist, time.'}
          </SheetDescription>
        </SheetHeader>

        {isCreating ? (
          <AppointmentWizard
            studioId={studioId}
            userId={userId}
            mode="drawer"
            defaultSlot={defaultStart ? defaultStart.toISOString() : null}
            onSuccess={() => {
              onOpenChange(false)
              onSuccess()
            }}
            onCancel={() => onOpenChange(false)}
          />
        ) : (
          /* Edit mode: handled on the appointment detail page */
          <div className="flex-1 overflow-y-auto px-6 py-6 text-sm text-muted-foreground">
            Edit functionality is available on the appointment detail page.
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

