/**
 * Smoke tests 3–5: Booking flows
 *
 * Test 3  — Unified wizard step order (Client → Service → Artist → Time)
 *           verified on BOTH surfaces: full-page and drawer.
 * Test 4  — Public booking end-to-end (page loads)
 * Test 5  — Consent signing page renders
 */
import { test, expect } from './fixtures'
import { test as publicTest } from '@playwright/test'

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Expected step labels in order for the unified wizard. */
const EXPECTED_STEPS = ['Client', 'Service', 'Artist', 'Time']

/**
 * Assert that the step indicator visible inside `container` shows steps in
 * the canonical order Client → Service → Artist → Time.
 *
 * When the studio has ≤1 artist the Artist step is auto-skipped, so the
 * indicator only shows 3 steps — we verify that the ones shown are a
 * contiguous prefix/suffix of the expected sequence (never reordered).
 */
async function assertStepOrder(
  container: import('@playwright/test').Locator,
) {
  // BookingStepIndicator renders step labels as small text inside <nav>
  const stepLabels = container.locator('nav[aria-label] span').filter({
    hasText: /^(Client|Service|Artist|Time)$/,
  })

  const labels = await stepLabels.allTextContents()
  const trimmed = labels.map((l) => l.trim()).filter(Boolean)

  // Must have 3 or 4 steps (4 when multi-artist studio, 3 when single/zero artist)
  expect(trimmed.length).toBeGreaterThanOrEqual(3)

  // Step 0 must always be Client
  expect(trimmed[0]).toBe('Client')
  // Step 1 must always be Service
  expect(trimmed[1]).toBe('Service')
  // Last step must always be Time
  expect(trimmed[trimmed.length - 1]).toBe('Time')

  // All labels must be a subsequence of EXPECTED_STEPS (never reordered)
  let ei = 0
  for (const label of trimmed) {
    while (ei < EXPECTED_STEPS.length && EXPECTED_STEPS[ei] !== label) ei++
    expect(EXPECTED_STEPS[ei]).toBe(label)
    ei++
  }
}

// ─── Test 3A: Full-page wizard (/appointments/new) ───────────────────────────

test('appointment wizard full-page: correct step order', async ({ signedInPage: page }) => {
  await page.goto('/appointments/new', { waitUntil: 'domcontentloaded' })
  await expect(page.locator('h1, h2').first()).toBeVisible({ timeout: 15_000 })

  // The wizard step indicator is inside [data-testid="appointment-wizard"]
  const wizardEl = page.locator('[data-testid="appointment-wizard"]').first()
  await expect(wizardEl).toBeVisible({ timeout: 10_000 })

  await assertStepOrder(wizardEl)

  // Step 0 content: client finder search input must be present
  await expect(
    page.locator('input[placeholder*="Search"]').first(),
  ).toBeVisible({ timeout: 8_000 })
})

// ─── Test 3B: Drawer wizard (triggered from appointments list) ───────────────

test('appointment wizard drawer: correct step order and same fields', async ({
  signedInPage: page,
}) => {
  await page.goto('/appointments', { waitUntil: 'domcontentloaded' })
  await expect(page).toHaveURL(/appointments/, { timeout: 15_000 })

  // Trigger the drawer via the "New appointment" button
  const newBtn = page
    .locator('button, a')
    .filter({ hasText: /new appointment|book|add/i })
    .first()

  if (!(await newBtn.isVisible({ timeout: 5_000 }))) {
    // If the page doesn't surface the button in this viewport, skip gracefully
    test.skip()
    return
  }

  await newBtn.click()

  // The Sheet/Drawer opens — wait for the wizard step indicator inside it
  const drawerWizard = page
    .locator('[role="dialog"] [data-testid="appointment-wizard"]')
    .first()
  await expect(drawerWizard).toBeVisible({ timeout: 10_000 })

  await assertStepOrder(drawerWizard)

  // Step 0 content: client finder search input must be present inside the drawer
  const dialog = page.locator('[role="dialog"]').first()
  await expect(
    dialog.locator('input[placeholder*="Search"]').first(),
  ).toBeVisible({ timeout: 8_000 })
})

// ─── Test 3C: Keyboard shortcut N still navigates to /appointments/new ───────

test('keyboard shortcut N navigates to /appointments/new', async ({
  signedInPage: page,
}) => {
  await page.goto('/dashboard', { waitUntil: 'domcontentloaded' })

  // Focus the body so the keydown fires on window (not inside an input)
  await page.locator('body').click()
  await page.keyboard.press('n')

  await expect(page).toHaveURL(/\/appointments\/new/, { timeout: 10_000 })
})

// ─── Test 4: Public booking end-to-end (page loads) ─────────────────────────

publicTest('public booking page loads', async ({ page }) => {
  const testSlug = process.env.TEST_STUDIO_SLUG ?? 'demo-studio'
  await page.goto(`/book/${testSlug}`)
  await expect(page.locator('body')).toBeVisible({ timeout: 15_000 })
  await expect(page).not.toHaveURL(/500|crash/, { timeout: 10_000 })
})

// ─── Test 5: Consent signing page renders ────────────────────────────────────

publicTest('consent signing page renders', async ({ page }) => {
  await page.goto('/consent/smoke-test-token-invalid')
  await expect(page.locator('body')).toBeVisible({ timeout: 15_000 })
  const title = await page.title()
  expect(title).not.toMatch(/500|error/i)
})

